import React, { ReactElement, useEffect, useMemo, useState } from \"react\";
import { Room } from \"matrix-js-sdk/src/models/room\";
import { RoomMember } from \"matrix-js-sdk/src/models/room-member\";
import { MatrixEvent } from \"matrix-js-sdk/src/models/event\";
import { logger } from \"matrix-js-sdk/src/logger\";

import dis from \"../dispatcher/dispatcher\";
import { Action } from \"../dispatcher/actions\";
import { MatrixClientPeg } from \"../MatrixClientPeg\";
import { getPrimaryPermalinkEntity } from \"../utils/permalinks/Permalinks\";
import { PillType } from \"../components/views/elements/Pill\";
import { ButtonEvent } from \"../components/views/elements/AccessibleButton\";
import RoomAvatar from \"../components/views/avatars/RoomAvatar\";
import MemberAvatar from \"../components/views/avatars/MemberAvatar\";

interface Args {
    room?: Room;
    type?: PillType;
    url?: string;
}

interface HookResult {
    avatar: ReactElement | null;
    text: string | null;
    onClick: ((e: ButtonEvent) => void) | null;
    resourceId: string | null;
    type: PillType | \"space\" | null;
}

/** Resolve the entity behind a pill without changing its original URL. */
export function usePermalink({ room, type, url }: Args): HookResult {
    const resourceId = url ? getPrimaryPermalinkEntity(url) : null;
    const pillType = type || {
        \"@\": PillType.UserMention,
        \""'!": PillType.RoomMention,
        "#": PillType.RoomMention,
    }[resourceId?.[0]] || null;

    const localMember = pillType === PillType.UserMention && resourceId ? room?.getMember(resourceId) : null;
    const fallbackMember = useMemo(
        () => (pillType === PillType.UserMention && resourceId ? new RoomMember(null, resourceId) : null),
        [pillType, resourceId],
    );
    const [profile, setProfile] = useState<{ userId: string; member: RoomMember } | null>(null);

    useEffect(() => {
        if (pillType !== PillType.UserMention || !resourceId || localMember) return;

        let cancelled = false;
        MatrixClientPeg.get()
            .getProfileInfo(resourceId)
            .then((resp) => {
                if (cancelled) return;
                fallbackMember.name = resp.displayname;
                fallbackMember.rawDisplayName = resp.displayname;
                fallbackMember.events.member = {
                    getContent: () => ({ avatar_url: resp.avatar_url }),
                    getDirectionalContent: function () {
                        return this.getContent();
                    },
                } as MatrixEvent;
                setProfile({ userId: resourceId, member: fallbackMember });
            })
            .catch((err) => {
                logger.error("Could not retrieve profile data for " + resourceId + ":", err);
            });
        return () => {
            cancelled = true;
        };
    }, [pillType, resourceId, localMember, fallbackMember]);

    if (pillType === PillType.AtRoomMention) {
        return {
            avatar: room ? <RoomAvatar room={room} width={16} height={16} aria-hidden="true" /> : null,
            text: "@room",
            onClick: null,
            resourceId: room?.roomId ?? null,
            type: pillType,
        };
    }

    if (!resourceId) {
        return { avatar: null, text: null, onClick: null, resourceId: null, type: null };
    }

    if (pillType === PillType.RoomMention) {
        const resolvedRoom = resourceId[0] === "#"
            ? MatrixClientPeg.get().getRooms().find((r) =>
                  r.getCanonicalAlias() === resourceId || r.getAltAliases().includes(resourceId),
              )
            : MatrixClientPeg.get().getRoom(resourceId);
        return {
            avatar: resolvedRoom ? <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" /> : null,
            text: resolvedRoom?.name || resourceId,
            onClick: null,
            resourceId,
            type: resolvedRoom?.isSpaceRoom() ? "space" : pillType,
        };
    }

    if (pillType === PillType.UserMention) {
        const member = localMember || (profile?.userId === resourceId ? profile.member : fallbackMember);
        return {
            avatar: member ? <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle /> : null,
            text: member?.rawDisplayName || resourceId,
            onClick: (e: ButtonEvent) => {
                e.preventDefault();
                dis.dispatch({ action: Action.ViewUser, member });
            },
            resourceId,
            type: pillType,
        };
    }

    return { avatar: null, text: null, onClick: null, resourceId: null, type: null };
}
